int minDistance = pkArrow->GetValue(4) + pkAttacker->GetPoint(POINT_BOW_DISTANCE) * 100;
int maxDistance = pkArrow->GetValue(5) + pkAttacker->GetPoint(POINT_BOW_DISTANCE) * 100;

int iPercent = 100;
// MT2009_PLUS_ARROW_RANGE_V1: the fade below runs from value4 (full
// strength) to value5 (value2 per cent, twice that against a monster). The
// elemental arrows - Ognista, Trujaca, Lodowa, Przekleta Strzala (8006-8009)
// - carry 0 in all three, so every shot of theirs past point-blank came to
// 0 per cent: an archer with one of them dealt no damage at all. An arrow
// without a fade range (value5 not past value4) strikes at full strength,
// as a silver arrow does against a monster at any distance.
if (pkArrow->GetValue(5) > pkArrow->GetValue(4) && iDist > minDistance)
{
	int arrow_damage_percent = pkArrow->GetValue(2);
	int minDamagePercent = pkVictim->IsNPC() ? MIN(arrow_damage_percent * 2, 100) : arrow_damage_percent;
	if (iDist >= maxDistance)
		iPercent = minDamagePercent;
	else
	{
		int distDelta = maxDistance - minDistance;
		int distProgress = ((iDist - minDistance) * 100) / distDelta;

		int percentDelta = 100 - minDamagePercent;
		iPercent = MAX(100 - percentDelta * distProgress / 100, minDamagePercent);
	}
}

