// CalcArrowDamage): full strength up to 5 m (500) plus the bow's reach bonus (POINT_BOW_DISTANCE, in metres),
// then 5 per cent less for every further full metre - 50 per cent at 15 m, nothing from 25 m - against a monster
// and a player alike, whatever the arrow. A quiver - an arrow with a real-time limit, Kolczan 8010-8012
// (server-patches/quiver) - does not fade. It replaces MT2009_PLUS_ARROW_RANGE_V1's fade by the arrow's
// value2 / value4 / value5 (all 0 now, strzaly_global.sql).
bool bMt2009Quiver = false;
for (int i = 0; i < ITEM_LIMIT_MAX_NUM; ++i)
	if (pkArrow->GetLimitType(i) == LIMIT_REAL_TIME)
		bMt2009Quiver = true;
int iGap = (iDist / 100) - 5 - pkAttacker->GetPoint(POINT_BOW_DISTANCE);
int iPercent = bMt2009Quiver ? 100 : 100 - (iGap * 5);
